1	// The LIVE half of the review's inputs: what the tree says right now, which no
2	// window applies to. Three questions the record cannot answer -
3	//
4	//   what does each mounted skill declare about itself, and what does its body cost;
5	//   what does each active rule enforce, and does a RULES.md line say the same thing;
6	//   what has this repo accepted away or overridden.
7	//
8	// …plus the one date an `adoption` rule needs: when this repo declared the pack.
9	import { readFileSync, existsSync } from 'node:fs';
10	import { join } from 'node:path';
11	import { execFileSync } from 'node:child_process';
12	
13	const engine = (root, mod) => {
14	  const shared = join(root, '.claudinite', 'shared', 'engine', mod);
15	  return existsSync(shared) ? shared : join(root, 'engine', mod);
16	};
17	
18	const read = (path) => { try { return readFileSync(path, 'utf8'); } catch { return ''; } };
19	
20	// The tools a skill's result triggers name - the denominator
21	// `result-trigger-follows-every-call` is asked against. A trigger matching tools by
22	// regex names no one tool, so it contributes none and the rule reads *not recorded*
23	// rather than guessing which tool it meant.
24	export const toolsNamedBy = (triggers) => [...new Set((triggers ?? [])
25	  .map((t) => t.tool).filter((t) => typeof t === 'string'))];
26	
27	// Every mounted skill as a review subject: what it declares, what its body costs,
28	// and which pack it came from.
29	export async function readSkills(root, packs) {
30	  const { skillMetadata } = await import(engine(root, 'pack_loader/skill-frontmatter.mjs'));
31	  const { estimateTokensOf } = await import(engine(root, 'pack_loader/token-estimate.mjs'));
32	  const out = [];
33	  for (const pack of packs) {
34	    for (const name of pack.skills ?? []) {
35	      const dir = join(pack.dir, 'skills', name);
36	      const meta = skillMetadata(dir);
37	      const body = read(join(dir, 'SKILL.md'));
38	      out.push({
39	        id: name,
40	        pack: pack.id,
41	        dir,
42	        // The body past its frontmatter - what a load actually costs the session.
43	        tokens: estimateTokensOf(body.replace(/^---[\s\S]*?\n---\n/, '')),
44	        expect: meta.usage?.expect ?? null,
45	        usageProblems: meta.usage?.problems ?? [],
46	        tools: toolsNamedBy(meta.toolResultTriggers),
47	        triggers: meta.forceLoadPaths.length + meta.toolCallTriggers.length
48	          + meta.promptTriggers.length + meta.toolResultTriggers.length,
49	      });
50	    }
51	  }
52	  return out;
53	}
54	
55	// A rule id stated in the same pack's RULES.md, in backticks. That is the whole
56	// definition of a prose twin: a twin expressed any other way is not seen, and the
57	// review reports how many rules it judged twin-less so a reader can weigh what the
58	// definition missed rather than trust a number that hid it.
59	export function hasProseTwin(pack, ruleId) {
60	  const prose = read(join(pack.dir, pack.prose ?? 'RULES.md'));
61	  return prose.includes(`\`${ruleId}\``);
62	}
63	
64	// The active rules, split into the two subject kinds the rules judge apart: a guard
65	// is a `scope: "action"` declaration, judged per tool call, and everything else is a
66	// check the sweeps run.
67	export function readRules(packs, packRules) {
68	  const byPack = new Map(packs.map((p) => [p.id, p]));
69	  const out = { check: [], guard: [] };
70	  for (const rule of packRules) {
71	    const pack = [...byPack.values()].find((p) => (p.rules ?? []).includes(rule)
72	      || (p.skillChecks ?? []).includes(rule));
73	    const subject = {
74	      id: rule.id,
75	      pack: pack?.id ?? null,
76	      severity: rule.severity ?? null,
77	      scope: rule.spec?.scope ?? rule.scope ?? null,
78	      ownerSkill: rule.ownerSkill ?? null,
79	      proseTwin: pack ? hasProseTwin(pack, rule.id) : false,
80	    };
81	    out[subject.scope === 'action' ? 'guard' : 'check'].push(subject);
82	  }
83	  return out;
84	}
85	
86	// What this repo has accepted away or overridden for a rule: `accept` entries name
87	// the rule and the file, and a `rules` override to advisory is the same decision
88	// taken once for the whole tree, which is why the rule counts them together.
89	export function acceptanceReader(config) {
90	  const accepts = Array.isArray(config?.accept) ? config.accept : [];
91	  const overrides = config?.rules ?? {};
92	  return (ruleId) => {
93	    const reasons = accepts.filter((a) => a?.rule === ruleId);
94	    const overridden = overrides[ruleId] === 'advisory' ? 1 : 0;
95	    return reasons.length + overridden;
96	  };
97	}
98	
99	// The reasons behind those acceptances, for the finding's evidence - listed
100	// together is what makes a structural exemption visible as one.
101	export const acceptanceReasons = (config, ruleId) => (Array.isArray(config?.accept) ? config.accept : [])
102	  .filter((a) => a?.rule === ruleId)
103	  .map((a) => ({ file: a.file ?? a.path ?? null, reason: a.reason ?? a.why ?? null }));
104	
105	// When this repo first declared a pack - the adoption window's start. Read from the
106	// settings file's own history, deepened as far as the checkout reaches. A shallow
107	// clone that does not reach it answers null, and the `adoption` rules then read
108	// *not recorded* rather than judging against a date that is really the clone's.
109	export function packDeclaredAt(root, packId) {
110	  const run = (args) => execFileSync('git', args,
111	    { cwd: root, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
112	  try {
113	    const first = run(['log', '--reverse', '--format=%H %aI',
114	      '-S', `"${packId}"`, '--', '.claudinite-settings.json']).trim().split('\n')[0];
115	    if (!first) return null;
116	    const [sha, at] = first.split(' ');
117	    // The earliest commit that MENTIONS the pack is the one that declared it only
118	    // if the commit before it did not already carry it. Without that second read
119	    // the search answers with the earliest commit the checkout happens to reach,
120	    // which on a shallow clone is the clone's own horizon - and the adoption
121	    // window then becomes a property of how deeply this checkout was fetched, so
122	    // one review over one record finds different things on two checkouts.
123	    let parent = null;
124	    try { parent = run(['rev-parse', '--verify', '-q', `${sha}^`]).trim(); } catch { parent = null; }
125	    if (!parent) {
126	      // No parent here: either the repository's own first commit, which is a real
127	      // answer, or a shallow boundary, where the declaration predates everything
128	      // we can see and its date is simply not knowable.
129	      return run(['rev-parse', '--is-shallow-repository']).trim() === 'true' ? null : at;
130	    }
131	    let before = '';
132	    try { before = run(['show', `${parent}:.claudinite-settings.json`]); } catch { before = ''; }
133	    return before.includes(`"${packId}"`) ? null : at;
134	  } catch { return null; }
135	}
136	
137	export const ADOPTION_WEEKS = 4;
138	
139	// Is the pack's adoption window still open, closed, or unknowable? A skill expecting
140	// `adoption` is judged only once the window has CLOSED - inside it, a skill that has
141	// not loaded yet may simply not have been reached.
142	export function adoptionWindow(declaredAt, now) {
143	  if (!declaredAt) return null;
144	  const from = new Date(declaredAt);
145	  const to = new Date(from);
146	  to.setUTCDate(to.getUTCDate() + ADOPTION_WEEKS * 7);
147	  return { from: from.toISOString(), to: to.toISOString(), closed: new Date(now) >= to };
148	}
