1	#!/usr/bin/env node
2	// The provenance log's one tool (the provenance design, #2136): every flow that
3	// creates or changes an element appends through it, the marking pass runs through it,
4	// and a maintainer checks a pack with it. Two roots - a canon's `packs/<id>` and a
5	// member's `.claudinite/local/packs/<id>` - resolved from the id, or `--all` for every
6	// pack under both. The grammar and the codemods are the engine helper's
7	// (engine/checks/helpers/provenance.mjs); this is the command line over them, and
8	// the parts that need git or a scrub.
9	//
10	//   node <path-to-this-file> mark <pack>|--all [--dry-run]
11	//   node <path-to-this-file> check <pack>|--all
12	//   node <path-to-this-file> convert-references <pack>|--all
13	//   node <path-to-this-file> append <pack> <element> [--kind <kind>] [--date <YYYY-MM-DD>] [--changed] < entry.md
14	//   node <path-to-this-file> reduce <file> [--public]
15	//   node <path-to-this-file> history <pack> <element>
16	//   node <path-to-this-file> brief <pack> [<element>…]
17	//   node <path-to-this-file> apply <pack> <brief.md> [--backfill]
18	//
19	// In a member the path is .claudinite/shared/packs/claudinite-growth/provenance.mjs; in
20	// the canon, packs/claudinite-growth/provenance.mjs. The append reads one entry in the
21	// file grammar from stdin - `## <date> · <kind> · <title>` and its `- **Field:** …`
22	// lines - and refuses one that carries a secret, since a decision log is prose an
23	// agent writes and the one place nothing else scans.
24	//
25	// A provenance file is append-only for every flow but one: a change recorded now cannot
26	// have happened before the change recorded last. The backfill is the exception by design,
27	// because it derives a history that already happened - `--backfill` on `append` and
28	// `apply` writes entries dated in the past, in date order over the whole file, and is the
29	// only lane that does.
30	import { execFileSync } from 'node:child_process';
31	import { readFileSync } from 'node:fs';
32	import { join } from 'node:path';
33	import { pathToFileURL } from 'node:url';
34	// A namespace import, guarded in `main`: the pack and engine lanes deliver on separate
35	// cadences, and a mount whose engine predates the helper must say so rather than fault
36	// on a missing named export.
37	import * as provenance from '../../engine/checks/helpers/provenance.mjs';
38	import * as conventions from '../../engine/pack_loader/pack-conventions.mjs';
39	import { scrub } from './capture-log.mjs';
40	
41	// The version log's name, with the same lane-skew fallback as the helper import above.
42	const VERSIONS_FILE = conventions.VERSIONS_FILE ?? 'VERSIONS.md';
43	
44	const {
45	  checkoutIo, auditPack, markPack, convertReferences, appendedText, backfilledText, parseEntryText, packCarriers,
46	  provenanceFiles, reduceFile, fileOfId, elementIdOf, ruleBlocks, skillShape, parseEntries, renderEntry,
47	  PACK_ROOTS, PROVENANCE_DIR, DECLINED_FILE, DECLINED_KIND, PACK_ELEMENT,
48	} = provenance;
49	
50	const USAGE = `usage: provenance.mjs <command> …
51	  mark <pack>|--all [--dry-run]          markers, bodies and empty files for every carrier
52	  check <pack>|--all                     what each file is named by, and every fault
53	  convert-references <pack>|--all        the references.md of a pack into its elements' files
54	  append <pack> <element> [--kind K] [--date D] [--changed] [--backfill] < entry.md
55	  reduce <file> [--public]               the promotion reduction, to stdout
56	  history <pack> <element>               one element's raw evidence from git, VERSIONS.md and the README
57	  brief <pack> [<element>…]              the backfill brief: every pull request once, a draft entry per event
58	  apply <pack> <brief.md> [--backfill]   append every drafted entry of an edited brief, each once
59	  --backfill                             the backfill's lane: entries dated in the past, written in
60	                                         date order over the file, creating one the marking pass
61	                                         could not. every other caller appends, and only at the end`;
62	
63	// --- packs and roots ---------------------------------------------------------------
64	
65	export function resolvePack(root, id, io = checkoutIo(root)) {
66	  if (id.includes('/')) return io.exists(`${id}/pack.mjs`) ? id.replace(/\/+$/, '') : null;
67	  for (const r of PACK_ROOTS) if (io.exists(`${r}/${id}/pack.mjs`)) return `${r}/${id}`;
68	  return null;
69	}
70	
71	export function allPacks(io) {
72	  const out = [];
73	  for (const r of PACK_ROOTS) for (const name of (io.listDir(r) ?? []).sort()) if (io.exists(`${r}/${name}/pack.mjs`)) out.push(`${r}/${name}`);
74	  return out;
75	}
76	
77	// A copy-on-write io over another: what `--dry-run` runs the codemods against, so the
78	// report is the real one and the tree is untouched.
79	export function overlayIo(base) {
80	  const written = new Map();
81	  const removed = new Set();
82	  const listDir = (p) => {
83	    if (written.has(p)) return null;
84	    const names = new Set((removed.has(p) ? null : base.listDir(p)) ?? []);
85	    let any = names.size > 0 || base.listDir(p) !== null;
86	    for (const w of written.keys()) {
87	      if (w.startsWith(`${p}/`)) { names.add(w.slice(p.length + 1).split('/')[0]); any = true; }
88	    }
89	    for (const r of removed) names.delete(r.slice(p.length + 1));
90	    return any ? [...names] : null;
91	  };
92	  return {
93	    exists: (p) => (removed.has(p) ? false : written.has(p) || base.exists(p)),
94	    read: (p) => (removed.has(p) ? null : written.has(p) ? written.get(p) : base.read(p)),
95	    write: (p, t) => { written.set(p, t); removed.delete(p); },
96	    remove: (p) => { removed.add(p); written.delete(p); },
97	    listDir,
98	  };
99	}
100	
101	const git = (root, ...args) => { try { return execFileSync('git', args, { cwd: root, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }); } catch { return ''; } };
102	
103	// --- the commands ------------------------------------------------------------------
104	
105	export function mark(root, packs, { dryRun = false } = {}) {
106	  const real = checkoutIo(root);
107	  const io = dryRun ? overlayIo(real) : real;
108	  const lines = [];
109	  let empty = 0;
110	  for (const pack of packs) {
111	    lines.push(...markPack(pack, io));
112	    empty += auditPack(pack, io).empty.length;
113	  }
114	  lines.push(`${empty} empty provenance file${empty === 1 ? '' : 's'} under ${packs.length === 1 ? packs[0] : `${packs.length} packs`}${dryRun ? ' (dry run: nothing written)' : ''}`);
115	  return { lines, empty };
116	}
117	
118	// The audit as text: what each file is named by, then every fault. Exit status is the
119	// caller's: faults are anything but pending history.
120	export function check(root, packs) {
121	  const io = checkoutIo(root);
122	  const lines = [];
123	  let faults = 0;
124	  for (const pack of packs) {
125	    const a = auditPack(pack, io);
126	    const namedBy = new Map();
127	    const name = (id, by) => { if (!namedBy.has(id)) namedBy.set(id, []); namedBy.get(id).push(by); };
128	    for (const r of a.carriers.rules) if (r.slug) name(r.slug, `rule "${r.trigger}"`);
129	    for (const g of a.carriers.guidelines) if (g.slug) name(g.slug, `guideline "${g.trigger}" (${g.skill})`);
130	    for (const s of a.carriers.skills) if (s.present) name(s.name, `skill ${s.name} (${s.body ?? 'no body'})`);
131	    for (const c of a.carriers.checks) name(elementIdOf(c.id), `check ${c.id}`);
132	    for (const t of a.carriers.tasks) name(t.id, `task ${t.id}`);
133	    for (const d of a.carriers.declarations) name(d.id, `declared rule ${d.id}`);
134	    if (a.carriers.manifest) name(PACK_ELEMENT, 'the manifest');
135	    lines.push(`${pack}/${PROVENANCE_DIR}/`);
136	    const state = (f) => (f.status === 'retired' ? ' (retired)' : f.empty ? ' (empty)' : f.convertedOnly ? ' (conversion only, history pending)' : '');
137	    for (const [id, f] of [...a.files].sort()) lines.push(`  ${fileOfId(id)} ← ${(namedBy.get(id) ?? ['nothing']).join(', ')}${state(f)}`);
138	    // The declined log is named by no carrier, so it is listed rather than matched: a pass
139	    // that turned candidates down cannot be read off a listing that leaves it out.
140	    if (a.declined) lines.push(`  ${DECLINED_FILE} ← ${a.declined.entries.length} candidate${a.declined.entries.length === 1 ? '' : 's'} turned down`);
141	    const fault = (file, line, what) => { faults++; lines.push(`  ${file}${line ? `:${line}` : ''}: ${what}`); };
142	    for (const u of a.unmarked) fault(u.file, u.line, `"${u.trigger}" ends with no marker`);
143	    for (const d of a.dangling) fault(d.file, d.line, `${d.carrier} names ${fileOfId(d.id)}, which is ${d.retired ? 'retired' : 'no file'}`);
144	    for (const u of a.unnamed) fault(u.file, null, 'live, and named by no carrier');
145	    for (const n of a.noBody) fault(n.file, null, `skill ${n.skill} declares no body`);
146	    for (const m of a.markerInWorkflow) fault(m.file, m.line, `"${m.trigger}" carries a marker inside a workflow skill`);
147	    for (const e of a.parseErrors) fault(e.file, e.line, e.what);
148	    for (const e of a.entryFaults) fault(e.file, e.line, e.what);
149	    if (a.referencesDoc) fault(a.referencesDoc, null, 'a references.md still exists - convert-references retires it');
150	  }
151	  return { lines, faults };
152	}
153	
