203	  if (parsed.problems.length) return { problems: parsed.problems };
204	  const entry = { ...parsed.entry, ...(kind ? { kind } : {}), ...(date ? { date } : {}) };
205	  const written = [];
206	  for (const element of elements) {
207	    const declined = element === DECLINED_KIND || element === '_declined';
208	    const file = `${pack}/${PROVENANCE_DIR}/${declined ? DECLINED_FILE : fileOfId(element)}`;
