225	// The backfill brief: the carrier's commits through every rename, a pickaxe on the
226	// rule's lead-in, the pull requests those commits name, the VERSIONS.md rows naming
227	// them, and the README's history sentences. Tracker comments live on GitHub and are
228	// the session's to read.
229	export function history(root, pack, element) {
230	  const io = checkoutIo(root);
231	  const c = packCarriers(pack, io);
232	  const files = new Set();
233	  const triggers = [];
234	  for (const r of [...c.rules, ...c.guidelines]) if (r.slug === element) { files.add(r.file); triggers.push(r.trigger); }
235	  for (const s of c.skills) if (s.name === element) files.add(s.file);
236	  for (const x of c.checks) if (elementIdOf(x.id) === element) files.add(x.file);
237	  for (const t of c.tasks) if (t.id === element) files.add(t.dir);
238	  if (element === PACK_ELEMENT) files.add(`${pack}/pack.mjs`);
239	  const lines = [`# ${pack} · ${element}`];
240	  if (!files.size) { lines.push('named by no carrier of this pack'); return lines; }
241	  const prs = new Set();
242	  const note = (commits) => { for (const m of commits.matchAll(/\(#(\d+)\)/g)) prs.add(m[1]); };
243	  for (const f of files) {
244	    lines.push(`\n## commits touching ${f}`);
245	    const log = git(root, 'log', '--follow', '--format=%h %as %s', '--', f);
246	    lines.push(log.trim() || '(none - is the clone shallow?)');
247	    note(log);
248	  }
249	  for (const t of triggers) {
250	    lines.push(`\n## commits adding or removing "${t}"`);
251	    const log = git(root, 'log', '--format=%h %as %s', `-S${t}`, '--', pack);
252	    lines.push(log.trim() || '(none)');
253	    note(log);
254	  }
255	  lines.push('\n## pull requests those commits name');
256	  lines.push(prs.size ? [...prs].sort((a, b) => a - b).map((n) => `#${n}`).join(' ') : '(none)');
257	  const versions = io.read(`${pack}/${PROVENANCE_DIR}/${VERSIONS_FILE}`);
258	  if (versions) {
259	    lines.push('\n## VERSIONS.md rows naming them');
260	    const rows = versions.split('\n').filter((l) => l.startsWith('|') && [...prs].some((n) => l.includes(`#${n}`)));
261	    lines.push(rows.join('\n') || '(none)');
262	  }
263	  const readme = io.read(`${pack}/README.md`);
264	  if (readme) {
265	    lines.push('\n## README sentences that read as history');
266	    const tells = readme.split(/(?<=[.!?])\s+/).filter((s) => /#\d+|\buntil\b|\bdistilled from\b|\bkept as\b|\breplaced\b|\babsorbed\b|\b20\d\d-\d\d-\d\d\b/.test(s) || triggers.some((t) => s.includes(t)));
267	    lines.push(tells.map((s) => `- ${s.replace(/\s+/g, ' ').trim()}`).join('\n') || '(none)');
268	  }
269	  lines.push('\n## tracker comments');
270	  lines.push('read the promote tracker and the extract issues on GitHub; git does not hold them');
271	  return lines;
272	}
