274	// --- the backfill brief and its apply -----------------------------------------------
275	//
276	// A pack's history is a sequence of pull requests, each bearing or changing several
277	// elements, so the brief is written pull request first: the squash commit's body once
278	// (a merge here carries the whole review conversation's conclusion in it), then one
279	// draft entry per element and event with every field git can vouch for - the date, the
280	// kind, the actor by handle, the model from the trailer, the carrier as Mechanism, and
281	// Landed with the version VERSIONS.md cut for it. What git cannot vouch for - Source,
282	// Reason, Rejected, Retire when - is left out, never filled: the draft is a fact the
283	// session extends with the decision, or deletes where the commit was not one.
284	//
285	// An element's events are read from the carrier's own history rather than a pickaxe: a
286	// rule is walked back through every commit of its file - by slug, then by trigger, then
287	// by text - and is born where it first appears and reworded where its normalized text
288	// changed; a skill, a check, a task and the manifest are born at the oldest commit of
289	// their file and every later commit is a candidate the session judges. A commit that
290	// touched many packs is a sweep - a re-wrap, a rename, a marking pass - and is listed
291	// once, never drafted onto an element: the precedent records a sweep on `_pack.md`, and
292	// only where it changed the pack's shape.
293	
294	const SWEEP_PACKS = 5;
295	const TRAILER = /^(?:co-authored-by|claude-session|signed-off-by|reviewed-by|refs|fixes|closes|resolves):?\s/i;
296	const MODEL_TRAILER = /^co-authored-by:\s*(Claude\b[^<]*?)\s*</i;
297	const REFERENCED = /\b(Refs|Fixes|Closes|Resolves)\s*:?\s*#(\d+)/gi;
298	const PR_AT_END = /\s*\(#(\d+)\)\s*$/;
299	const ENTRY_FENCE = /^```entry (\S+)\s*$/;
300	const BODY_LINES = 60;
301	
302	// One commit, read once: what the squash merge carried, and how many packs it touched.
303	function commitInfo(root, sha, cache) {
304	  if (cache.has(sha)) return cache.get(sha);
