306	  const models = new Set();
307	  const lines = [];
308	  for (const l of (body ?? '').split('\n')) {
309	    const m = MODEL_TRAILER.exec(l.trim());
310	    if (m) { models.add(m[1].trim()); continue; }
311	    if (TRAILER.test(l.trim())) continue;
312	    lines.push(l.trimEnd());
313	  }
314	  const pr = PR_AT_END.exec(subject ?? '')?.[1] ?? null;
315	  // The keyword each reference was written with, kept rather than flattened: a body
316	  // saying `Fixes #956` and one saying `Refs #956` are different claims, and the entry
317	  // that reports either as the other sends a reader to the wrong kind of link. What the
318	  // PULL REQUEST body said can differ again, and git cannot see it - `brief` hands that
319	  // over rather than guessing (#2221).
320	  const refs = [];
321	  for (const [, keyword, n] of (body ?? '').matchAll(REFERENCED)) {
322	    if (n === pr || refs.some((r) => r.n === n)) continue;
323	    refs.push({ n, keyword: `${keyword[0].toUpperCase()}${keyword.slice(1).toLowerCase()}` });
324	  }
325	  // A merge commit's own trailer is GitHub's, naming the generic "Claude" where every
326	  // commit on the branch names the model that did the work. Reading the branch side back
327	  // keeps a known attribution from laundering into an unknown one (#2221).
328	  const branch = (parents ?? '').trim().split(/\s+/).filter(Boolean);
329	  if (branch.length > 1 && (!models.size || (models.size === 1 && models.has('Claude')))) {
330	    for (const l of git(root, 'log', '--format=%b', `${branch[0]}..${sha}`).split('\n')) {
331	      const m = MODEL_TRAILER.exec(l.trim());
