476	// The text a needle is matched against. A trigger is read off the carrier with its markup
477	// already dropped, so the same rule spelled `LSMinimumSystemVersion` at the path it came
478	// from matches nothing until both sides are stripped, and a bullet wrapped at 100 columns
479	// matches nothing until the newline is a space (#2253).
480	const searchable = (text) => text.replace(/[`*]/g, '').replace(/\s+/g, ' ');
481	// A table row names every element the table covers by construction - a README rule index, a
482	// version log, a check catalog - so the element's text appearing in one is evidence it was
483	// LISTED, never that it was carried there. The two texts are searched separately: the rows
484	// answer a different question from the file they sit in.
485	const withoutRows = (text) => text.split('\n').filter((l) => !l.trimStart().startsWith('|')).join('\n');
