487	// and minus the provenance log itself, which is a record ABOUT the element.
488	const couldCarry = (path) => /\.(md|mjs|json)$/.test(path) && !path.endsWith('.test.mjs') && !path.includes(`/${PROVENANCE_DIR}/`);
