490	// Several blobs' contents in one call. `--batch` answers `<sha> blob <size>` and then the
491	// bytes, so the sizes rather than the newlines are what delimit them.
492	function readBlobs(root, shas) {
493	  const out = new Map();
494	  if (!shas.length) return out;
495	  let buf;
496	  try {
497	    buf = execFileSync('git', ['cat-file', '--batch'], { cwd: root, input: `${shas.join('\n')}\n`, maxBuffer: 1 << 30, stdio: ['pipe', 'pipe', 'ignore'] });
498	  } catch { return out; }
499	  let at = 0;
500	  while (at < buf.length) {
501	    const nl = buf.indexOf(0x0a, at);
502	    if (nl < 0) break;
503	    const [sha, type, size] = buf.toString('utf8', at, nl).split(' ');
504	    if (type !== 'blob') break;
505	    const start = nl + 1;
506	    out.set(sha, buf.toString('utf8', start, start + Number(size)));
507	    at = start + Number(size) + 1;
508	  }
509	  return out;
510	}
