512	// Every revision of every file the pack's carriers could live in, oldest commit first, each
513	// as the two texts a needle is searched against. Read whole rather than by pickaxe: `-S`
514	// matches the literal needle in a diff, which a wrap or a backtick at the old path defeats
515	// silently, and its hits include the index rows that name every element anyway (#2253).
516	function carrierIndex(root, paths) {
517	  const revs = [];
518	  const wanted = new Set();
519	  for (const rec of git(root, 'log', '--reverse', '--format=%x01%H %as', '--raw', '--no-abbrev', '--no-renames', '--', ...paths).split('\x01')) {
520	    const lines = rec.split('\n');
521	    const [sha, date] = lines[0].split(' ');
522	    if (!sha) continue;
