534	    }
535	    if (files.length || lost.length) revs.push({ sha, date, files, lost });
536	  }
537	  const texts = readBlobs(root, [...wanted]);
538	  const carried = new Map();
539	  const listed = new Map();
540	  const size = new Map();
541	  for (const [sha, text] of texts) { carried.set(sha, searchable(withoutRows(text))); listed.set(sha, searchable(text)); size.set(sha, text.length); }
