205	    'packs/alpha/RULES.md': '- **Doing a thing** — the settled way. (doing-thing)\n\n- **Doing another** — plainly. (doing-another)\n',
206	    'packs/alpha/provenance/VERSIONS.md': '| Version | Date | What changed |\n|---|---|---|\n| 2 | 2026-08-02 | Said better (#8) |\n| 1 | 2026-07-01 | seed (#7) |\n',
207	  });
208	  writeFileSync(join(root, 'packs/alpha/RULES.md'), '- **Doing a thing** — the settled way, said better. (doing-thing)\n\n- **Doing another** — plainly. (doing-another)\n');
209	  commitAs(root, 'Said better (#8)\n\nThe old wording hid the point.\n\nCo-Authored-By: Claude Opus 5 <noreply@anthropic.com>\nClaude-Session: https://example.invalid/s', { email: '1+tester@users.noreply.github.com' });
210	  for (const p of ['beta', 'gamma', 'delta', 'epsilon']) {
211	    mkdirSync(join(root, `packs/${p}`), { recursive: true });
212	    writeFileSync(join(root, `packs/${p}/RULES.md`), '- **Elsewhere** — so.\n');
213	  }
214	  writeFileSync(join(root, 'packs/alpha/RULES.md'), '- **Doing a thing** - the settled way, said better. (doing-thing)\n\n- **Doing another** - plainly. (doing-another)\n\n- **Born in a sweep** - so. (born-in-sweep)\n');
215	  writeFileSync(join(root, 'packs/alpha/provenance/born-in-sweep.md'), '');
216	  commitAs(root, 'Hyphens everywhere (#9)');
