222	  commitAs(root, 'Bump pack versions: alpha 3 (#11)');
223	  writeFileSync(join(root, 'packs/alpha/pack.mjs'), '// alpha: the pack for doing things.\n//\n// No fingerprint: a thing is declared.\n\nexport default {\n  version: 3,\n  hidden: true,\n};\n');
